code.Python3:
# Time:  O(n)
# Space: O(1)

# array
class Solution(object):
    def possibleStringCount(self, word):
        """
        :type word: str
        :rtype: int
        """
        return len(word)-sum(word[i] != word[i+1] for i in range(len(word)-1))

